CREATE TABLE notification_preferences ( id UUID PRIMARY KEY, user_id UUID NOT NULL, event_type VARCHAR(50) NOT NULL, channel VARCHAR(20) NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT NOW(), updated_at TIMESTAMP NOT NULL DEFAULT NOW(),
CONSTRAINT uq_pref_user_event_channel UNIQUE (user_id, event_type, channel) );
CREATE INDEX idx_preferences_user ON notification_preferences (user_id);
